class Solution {
  public String mergeCharacters(String s, int k) {
    StringBuilder sb = new StringBuilder(s);
    boolean changed = true;
    while (changed) {
      changed = false;
      outer:
      for (int i = 0; i < sb.length(); i++) {
        for (int j = i + 1; j < sb.length() && j - i <= k; j++) {
          if (sb.charAt(i) == sb.charAt(j)) {
            sb.deleteCharAt(j);
            changed = true;
            break outer;
          }
        }
      }
    }
    return sb.toString();
  }
}
